        ["use.say"] = ("{0} is a {1}: index {2}, Abbe number {3}. {4} {5}: it returns {6}% of the light head-on. {7} at {8} mm.", "{0} — {1}: показатель {2}, число Аббе {3}. {4} {5}: при прямом взгляде возвращает {6}% света. {7} на {8} мм."),
